const expenses = [
  { paidBy: 'A', amount: 90, split: ['A', 'B', 'C'] },
  { paidBy: 'B', amount: 30, split: ['A', 'B', 'C'] },
];
const net = {};
for (const e of expenses) {
  const share = e.amount / e.split.length;
  net[e.paidBy] = (net[e.paidBy] ?? 0) + e.amount;
  for (const p of e.split) net[p] = (net[p] ?? 0) - share;
}
console.log(Object.entries(net).map(([k, v]) => k + '=' + v).join(' '));

const net = { A: 50, B: -10, C: -40 };
const cred = Object.entries(net).filter(([, v]) => v > 0);
const debt = Object.entries(net).filter(([, v]) => v < 0).map(([k, v]) => [k, -v]);
const tx = [];
let i = 0, j = 0;
while (i < cred.length && j < debt.length) {
  const amt = Math.min(cred[i][1], debt[j][1]);
  tx.push(`${debt[j][0]}->${cred[i][0]}:${amt}`);
  cred[i][1] -= amt; debt[j][1] -= amt;
  if (cred[i][1] === 0) i++;
  if (debt[j][1] === 0) j++;
}
console.log(tx.join(' '));

