class BookingService {
  async pay(method, amount) {
    switch (method) {
      case 'upi': return upiClient.collect(amount);
      case 'card': return cardGateway.charge(amount);
      case 'wallet': return walletApi.debit(amount);
      default: throw new Error('unsupported');
    }
  }
}
